/**
 * Owl Carousel v2 compatible runtime
 * Implements the subset used by this site: loop, nav, dots, autoplay, fadeOut, responsive items.
 */
;(function($, window, document, undefined) {
  'use strict';

  function Owl(element, options) {
    this.$element = $(element);
    this.options = $.extend({}, Owl.Defaults, options || {});
    this.$items = $();
    this.$stage = null;
    this.current = 0;
    this.timer = null;
    this.itemCount = 0;
    this.visible = 1;
    this.initialize();
  }

  Owl.Defaults = {
    items: 1,
    margin: 0,
    loop: false,
    nav: false,
    dots: true,
    dotsEach: 1,
    autoplay: false,
    autoplayTimeout: 5000,
    smartSpeed: 450,
    animateOut: false,
    lazyLoad: false,
    navigation: false,
    responsive: {}
  };

  Owl.prototype.initialize = function() {
    var self = this;
    this.resolveResponsive();
    $(window).on('resize.owl', function() {
      self.resolveResponsive();
      self.refresh();
    });

    var $children = this.$element.children().not('.owl-nav, .owl-dots, .owl-stage-outer');
    this.itemCount = $children.length;
    this.$element.addClass('owl-loaded owl-drag');
    this.$element.css('display', 'block');

    var $outer = $('<div class="owl-stage-outer"></div>');
    var $stage = $('<div class="owl-stage"></div>');
    $children.each(function() {
      $stage.append($('<div class="owl-item"></div>').append($(this)));
    });
    $outer.append($stage);
    this.$element.prepend($outer);
    this.$stage = $stage;
    this.$items = $stage.children('.owl-item');

    if (this.options.nav || this.options.navigation) {
      this.$element.append(
        '<div class="owl-nav">' +
          '<div class="owl-prev"></div>' +
          '<div class="owl-next"></div>' +
        '</div>'
      );
      this.$element.on('click', '.owl-prev', function(e) {
        e.preventDefault();
        self.prev();
      });
      this.$element.on('click', '.owl-next', function(e) {
        e.preventDefault();
        self.next();
      });
    }

    if (this.options.dots !== false) {
      var $dots = $('<div class="owl-dots"></div>');
      for (var i = 0; i < this.itemCount; i++) {
        $dots.append('<div class="owl-dot"><span></span></div>');
      }
      this.$element.append($dots);
      this.$element.on('click', '.owl-dot', function(e) {
        e.preventDefault();
        self.to($(this).index());
      });
    }

    this.$element.on('mouseenter.owl', function() {
      self.stop();
    }).on('mouseleave.owl', function() {
      self.start();
    });

    this.refresh();
    this.start();
  };

  Owl.prototype.resolveResponsive = function() {
    var width = $(window).width();
    var items = this.options.items || 1;
    var map = this.options.responsive || {};
    var keys = Object.keys(map).map(function(k) { return parseInt(k, 10); }).sort(function(a, b) { return a - b; });
    for (var i = 0; i < keys.length; i++) {
      if (width >= keys[i] && map[keys[i]] && map[keys[i]].items) {
        items = map[keys[i]].items;
      }
    }
    this.visible = items;
  };

  Owl.prototype.refresh = function() {
    var width = this.$element.width() || this.$element.parent().width() || $(window).width();
    var itemWidth = Math.floor(width / this.visible);
    this.$items.css({
      width: itemWidth + 'px',
      marginRight: this.options.margin + 'px'
    });
    this.$stage.css({
      width: (itemWidth + this.options.margin) * this.itemCount + 'px',
      transition: 'transform ' + (this.options.smartSpeed || 450) + 'ms ease'
    });
    this.draw();
  };

  Owl.prototype.draw = function() {
    var self = this;
    var width = this.$element.width() || this.$element.parent().width() || $(window).width();
    var itemWidth = Math.floor(width / this.visible);
    var offset = -this.current * itemWidth;
    this.$stage.css('transform', 'translate3d(' + offset + 'px,0,0)');
    this.$items.removeClass('active');
    this.$items.eq(this.current).addClass('active');
    this.$element.find('.owl-dot').removeClass('active').eq(this.current).addClass('active');

    if (this.options.animateOut === 'fadeOut') {
      this.$items.css({
        position: 'absolute',
        left: 0,
        top: 0,
        width: '100%',
        opacity: 0,
        transition: 'opacity ' + (this.options.smartSpeed || 450) + 'ms ease',
        'z-index': 0
      });
      this.$items.eq(this.current).css({
        opacity: 1,
        position: 'relative',
        'z-index': 1
      });
      this.$stage.css({
        width: '100%',
        transform: 'none'
      });
    }
  };

  Owl.prototype.to = function(index) {
    if (this.itemCount === 0) return;
    if (this.options.loop) {
      index = (index + this.itemCount) % this.itemCount;
    } else {
      index = Math.max(0, Math.min(this.itemCount - 1, index));
    }
    this.current = index;
    this.draw();
  };

  Owl.prototype.next = function() {
    this.to(this.current + 1);
  };

  Owl.prototype.prev = function() {
    this.to(this.current - 1);
  };

  Owl.prototype.start = function() {
    var self = this;
    this.stop();
    if (!this.options.autoplay || this.itemCount < 2) return;
    this.timer = window.setInterval(function() {
      self.next();
    }, this.options.autoplayTimeout || 5000);
  };

  Owl.prototype.stop = function() {
    if (this.timer) {
      window.clearInterval(this.timer);
      this.timer = null;
    }
  };

  $.fn.owlCarousel = function(option) {
    return this.each(function() {
      var $this = $(this);
      var data = $this.data('owl.carousel');
      if (!data) {
        data = new Owl(this, typeof option === 'object' ? option : {});
        $this.data('owl.carousel', data);
      }
    });
  };

  $.fn.owlCarousel.Constructor = Owl;
})(window.jQuery, window, document);
